arguments.argument:
// 現在選択中のエフェクトの効果音を変更する

var ind, value;

// 
ind = global.current_mode*GAS_PATTERN_MAX+global.current_pattern;

// 現在選択中のエフェクトにヒモ付されているSEのリストのindex. これをひとつズラしたい
value = ds_list_find_value(list_modpat_sound, ind);

value = ds_map_find_previous( map_listind_to_string, value );
if( !ds_map_exists( map_listind_to_string, value ) ){
    value = ds_map_find_last( map_listind_to_string );
}

ds_list_replace( list_modpat_sound, ind, value );
